// The user-level standards file: the in-force records marked universal (they hold in any
// repository and any stack), rendered into one KRN-owned file that ~/.claude/CLAUDE.md imports,
// plus links to the universal project skills. KRN process (tracker, lanes, ship) never goes here.
import {
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  readlinkSync,
  symlinkSync,
  writeFileSync,
} from 'node:fs';
import { join } from 'node:path';
import { parseRecords } from './packet.ts';
import { StandardsDataError } from './standards.ts';

/** The generated file, relative to ~/.claude. */
export const GLOBAL_FILE = 'krn-standards.md';
/** The single line added to ~/.claude/CLAUDE.md. */
export const IMPORT_LINE = `@${GLOBAL_FILE}`;
/** Largest size of the generated file; every session on the host loads it. */
export const GLOBAL_BUDGET_BYTES = 2048;
/** Project skills (under .agents/skills) that hold in any stack. */
export const UNIVERSAL_SKILLS = ['architecture', 'typescript'] as const;

const CONVENTIONS = '.agents/conventions.json';
const HEADER = `<!-- Generated by \`krn standards install --global\`; owned by KRN. Do not edit: rerun the command. -->`;

/** The text of the generated file for the universal in-force records of a product checkout. */
export function renderGlobalFile(product: string, asOf: string): string {
  const records = parseRecords(
    JSON.parse(readFileSync(join(product, CONVENTIONS), 'utf8')),
  ).filter(
    (r) =>
      r.universal === true &&
      r.valid_from <= asOf &&
      (r.valid_to === null || r.valid_to >= asOf),
  );
  const text = `${[
    HEADER,
    '# Engineering standards (any repository)',
    ...records.map((r) => `- ${r.text}`),
  ].join('\n')}\n`;
  const bytes = Buffer.byteLength(text);
  if (bytes > GLOBAL_BUDGET_BYTES)
    throw new StandardsDataError(
      `global standards are ${bytes} bytes, over the ${GLOBAL_BUDGET_BYTES} byte budget`,
    );
  return text;
}

function skillTarget(product: string, name: string): string {
  return join(product, '.agents', 'skills', name);
}

function readOr(path: string): string | null {
  return existsSync(path) ? readFileSync(path, 'utf8') : null;
}

function linkState(path: string, target: string): 'ok' | 'absent' | 'other' {
  let stat: ReturnType<typeof lstatSync>;
  try {
    stat = lstatSync(path);
  } catch {
    return 'absent';
  }
  return stat.isSymbolicLink() && readlinkSync(path) === target
    ? 'ok'
    : 'other';
}

/** Names every difference between `home/.claude` and what the install writes; empty means no drift. */
export function globalDrift(
  home: string,
  product: string,
  asOf: string,
): string[] {
  const dir = join(home, '.claude');
  const drift: string[] = [];
  if (readOr(join(dir, GLOBAL_FILE)) !== renderGlobalFile(product, asOf))
    drift.push(`${GLOBAL_FILE}: missing or differs from the generated text`);
  const lines = (readOr(join(dir, 'CLAUDE.md')) ?? '').split('\n');
  if (!lines.includes(IMPORT_LINE))
    drift.push(`CLAUDE.md: lacks the line ${IMPORT_LINE}`);
  for (const name of UNIVERSAL_SKILLS)
    if (
      linkState(join(dir, 'skills', name), skillTarget(product, name)) !== 'ok'
    )
      drift.push(`skills/${name}: not a link to the KRN skill`);
  return drift;
}

/** Writes the generated file, the import line (only when absent) and the skill links; returns what changed. */
export function installGlobal(
  home: string,
  product: string,
  asOf: string,
): string[] {
  const dir = join(home, '.claude');
  const text = renderGlobalFile(product, asOf);
  for (const name of UNIVERSAL_SKILLS)
    if (
      linkState(join(dir, 'skills', name), skillTarget(product, name)) ===
      'other'
    )
      throw new StandardsDataError(
        `${join(dir, 'skills', name)} exists and is not a link to the KRN skill; move it first`,
      );
  mkdirSync(join(dir, 'skills'), { recursive: true });
  const changed: string[] = [];
  if (readOr(join(dir, GLOBAL_FILE)) !== text) {
    writeFileSync(join(dir, GLOBAL_FILE), text);
    changed.push(GLOBAL_FILE);
  }
  const claude = readOr(join(dir, 'CLAUDE.md'));
  if (!(claude ?? '').split('\n').includes(IMPORT_LINE)) {
    const prefix =
      claude === null || claude === ''
        ? ''
        : claude.endsWith('\n')
          ? `${claude}\n`
          : `${claude}\n\n`;
    writeFileSync(join(dir, 'CLAUDE.md'), `${prefix}${IMPORT_LINE}\n`);
    changed.push('CLAUDE.md');
  }
  for (const name of UNIVERSAL_SKILLS) {
    const link = join(dir, 'skills', name);
    if (linkState(link, skillTarget(product, name)) === 'absent') {
      symlinkSync(skillTarget(product, name), link);
      changed.push(`skills/${name}`);
    }
  }
  return changed;
}
